mapper.select:


    inner join sys_user u on u.user_name = dexpbase.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    dexpbase.del_flag = '0'

        AND dexpbase.title like concat('%', #{title}, '%')

     and dexpbase.tree_id = #{treeId}
     and dexpbase.content = #{content}
     and dexpbase.file_link = #{fileLink}


${params.dataScope}
order BY create_time desc
